import type { Timestamp } from '@hierarchidb/common-types';
import type { LocationPointProperties, LocationPointSource } from '../../common/entities/LocationPoint.js';
import { createLocationPointProperties } from '../pointFactories.js';

export const IDE_GSM_LOCATION_HEADER = [
  'CapitalCity',
  'Latitude',
  'Longitude',
  'Region',
  'Country',
  'Habitable',
  'Population',
  'Employment',
  'EmplyomentA',
  'EmploymentM1',
  'EmploymentM2',
  'EmploymentM3',
  'EmploymentM4',
  'EmploymentM5',
  'EmploymentS',
  'EmploymentA2',
  'GDP',
  'GDPA',
  'GDPM1',
  'GDPM2',
  'GDPM3',
  'GDPM4',
  'GDPM5',
  'GDPS',
  'GDPA2',
  'Area',
  'Mining',
  'Grate',
  'Plimit',
] as const;

export type IdeGsmLocationPayload = {
  schemaVersion: 1;
  metadata: Record<string, string>;
  admin1Name?: string;
  countryName?: string;
  habitable?: number;
};

export type IdeGsmLocationPoint = LocationPointProperties<IdeGsmLocationPayload>;

export type CountryCodeResolver = (countryName: string) => string | undefined;

const DEFAULT_COUNTRY_CODE_BY_NAME = new Map([
  ['japan', 'JP'],
  ['united states', 'US'],
  ['united states of america', 'US'],
  ['china', 'CN'],
  ['korea, republic of', 'KR'],
  ['south korea', 'KR'],
  ['india', 'IN'],
  ['france', 'FR'],
  ['germany', 'DE'],
  ['united kingdom', 'GB'],
  ['canada', 'CA'],
  ['australia', 'AU'],
]);

export function parseIdeGsmCsv(
  csv: string,
  options: { fetchedAt?: Timestamp; countryCodeResolver?: CountryCodeResolver } = {},
): IdeGsmLocationPoint[] {
  const rows = splitCsvLines(csv);
  if (rows.length === 0) return [];
  const header = rows[0]!;
  const indices = resolveHeaderIndices(header);
  const now = options.fetchedAt ?? Date.now();
  const resolveCountryCode = options.countryCodeResolver ?? defaultCountryCodeResolver;
  const points: IdeGsmLocationPoint[] = [];

  for (let i = 1; i < rows.length; i++) {
    const cols = rows[i]!;
    const name = cols[indices.name] ?? '';
    const latitude = toNumber(cols[indices.latitude]);
    const longitude = toNumber(cols[indices.longitude]);
    if (!name || latitude === undefined || longitude === undefined) {
      continue;
    }
    const admin1Name = cols[indices.admin1] ?? '';
    const countryName = cols[indices.countryName] ?? '';
    const habitable = toInteger(cols[indices.habitable]);
    const countryCode = resolveCountryCode(countryName) ?? '';
    const metadata = collectMetadata(header, cols, indices.metadataStart);

    points.push(
      createLocationPointProperties({
        pid: toPid('ide-gsm', createUuid()),
        name,
        kind: resolveKind(name, habitable),
        latitude,
        longitude,
        gid0: countryCode,
        gid1: admin1Name || undefined,
        payload: {
          schemaVersion: 1,
          metadata,
          admin1Name: admin1Name || undefined,
          countryName: countryName || undefined,
          habitable: habitable ?? undefined,
        },
        source: toSource('ide-gsm', now, name),
      }),
    );
  }

  return points;
}

function resolveKind(name: string, habitable?: number): string {
  if (habitable === 1) return 'administrative';
  if (name.startsWith('Airport ')) return 'airport';
  if (name.startsWith('Port ')) return 'port';
  if (name.startsWith('Stn.')) return 'railway_station';
  return 'interchange';
}

function resolveHeaderIndices(header: string[]): {
  name: number;
  latitude: number;
  longitude: number;
  admin1: number;
  countryName: number;
  habitable: number;
  metadataStart: number;
} {
  const normalized = header.map((col) => col.trim());
  return {
    name: normalized.indexOf('CapitalCity'),
    latitude: normalized.indexOf('Latitude'),
    longitude: normalized.indexOf('Longitude'),
    admin1: normalized.indexOf('Region'),
    countryName: normalized.indexOf('Country'),
    habitable: normalized.indexOf('Habitable'),
    metadataStart: normalized.indexOf('Population'),
  };
}

function collectMetadata(header: string[], cols: string[], startIndex: number): Record<string, string> {
  const metadata: Record<string, string> = {};
  if (startIndex < 0) return metadata;
  for (let i = startIndex; i < header.length; i++) {
    const key = header[i]!;
    const value = cols[i];
    if (key && value !== undefined && value !== '') {
      metadata[key] = value;
    }
  }
  return metadata;
}

function splitCsvLines(csv: string): string[][] {
  return csv
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => line.split(',').map((col) => col.trim()));
}

function toNumber(value?: string): number | undefined {
  if (!value) return undefined;
  const num = Number(value);
  return Number.isFinite(num) ? num : undefined;
}

function toInteger(value?: string): number | undefined {
  if (!value) return undefined;
  const num = Number.parseInt(value, 10);
  return Number.isFinite(num) ? num : undefined;
}

function toSource(provider: string, fetchedAt: Timestamp, originalId?: string): LocationPointSource {
  return { provider, fetchedAt, originalId };
}

function defaultCountryCodeResolver(countryName: string): string | undefined {
  const trimmed = countryName.trim();
  if (!trimmed) return undefined;
  if (/^[A-Za-z]{2}$/.test(trimmed)) return trimmed.toUpperCase();
  return DEFAULT_COUNTRY_CODE_BY_NAME.get(trimmed.toLowerCase());
}

function toPid(prefix: string, rawId: string): string {
  return `${prefix}:${rawId}`;
}

function createUuid(): string {
  const randomUUID = globalThis.crypto?.randomUUID;
  if (typeof randomUUID === 'function') return randomUUID.call(globalThis.crypto);
  return `uuid-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}
